long long approx_distance(long long K,long long sx,long long sy,long long tx,long long ty){
    long long dx = sx>tx? sx-tx: tx-sx;
    long long dy = sy>ty? sy-ty: ty-sy;
    long long d = dx + dy;
    long long ans = d / K;
    if(d % K) ans++;
    return ans;
}

